# Generated by governance model version 3. Only the generator changes this file.
"""Merge watch: records misses after merges as `miss` issues, and never blocks anything.

The workflow `.github/workflows/merge-watch.yml` runs this script from the default branch's
checkout. It is never a required check. It reads the event, then GitHub through `gh api`,
and opens one miss record per miss, in the format `docs/agents/issue-tracker.md` gives
(Miss records), labelled `miss`.

On `push` to the default branch, for each pushed commit:

- the merged PR is the one whose squash commit it is. A commit that is only part of a merged
  PR's history is left to that PR's merge commit; a commit with no merged PR at all records a
  process miss, `push-without-pr`;
- a `Reverts:` line in the merged PR's body records an escape, `revert`, naming the reverted
  commit's PR;
- every review missing from the merged PR's head by its declared tier records one process
  miss, `missing-review`, listing each missing review by its Merge summary kind
  (`docs/agents/review.md`, Merge summary), then `merge-summary`. The tier requires
  `self-verification` and `merge-summary` at every tier, `bot-1` and `reviewer` from medium,
  and `bot-2` at high:
  - **the Merge summary**: the agent account's newest comment titled
    `## Merge summary: <tier> at <short sha>` for the declared tier and the head, whose second
    line reads by `parse_reviews`, listing every kind the tier requires and each bot slot's
    provider. One that doesn't read is absent: `merge-summary`;
  - **a bot slot** is filled by a completed review on the head from a provider enabled in the
    record at the merge's base, the commit before the squash commit. A PR can't lower its own
    requirements by changing that list. When GitHub answers that the base holds no record at
    all, as at an Initialize, the record the merge adds names the providers instead: there is
    no earlier list to lower, and the run says so in a `NOTE` line. With a readable summary,
    each slot needs the provider it names, and no provider fills two slots; without one, each
    enabled provider with a completed review fills one slot, in order. `PROVIDERS` holds one
    reader per provider, and a provider not on the list is never read or reported;
  - **`reviewer`**: the agent account's newest `Reviewer` status on the head is `success`;
  - **`self-verification`**, and **`security`** when the summary lists it, are present when a
    summary that reads writes them `clear`, since nothing else on GitHub shows them;
  - **a waiver**: any of those reviews counts as present when the repository owner's own PR
    comment waives it for this head, in the fixed form `WAIVER` reads. A summary writing
    `waived` with no such comment, a waiver naming another head, and one by any other
    account, the agent account included, count the review as missing.

  The repository owner is the owner in the repository's full name, a user account, as the
  generator requires. It doesn't check a condition a review bot's subsection in `review.md`
  puts on a Reviewer waiver, such as Copilot never judging fixed content alone; the Merge
  summary's writer does. A body with no readable `Risk:` line is judged at high.

  A merge whose base record is below version 3, such as an Upgrade's own PR, follows that
  version's review rules. This script judges what every version requires: the Reviewer's
  status from medium, and a Merge summary for the tier and head with a `Required reviews:`
  line of any kinds. Its review bots follow rules this script doesn't hold, so they aren't
  judged, an accepted transition exception: that PR's Reviewer checks them before the merge.
  The run says so in a `NOTE` line. A base record that can't be read or doesn't
  parse enables no provider, so its bot slots read as missing, a false miss.

  "No record" is GitHub's own answer for the path: HTTP 404 with the message `Not Found`
  (`NotFound`). Any other answer, a missing ref's 404 among them, is a read that failed. The
  workflow's token reads its own repository, so that answer can't mean the repository itself
  is out of reach. A base also holds no record after a merged PR deleted it, a change that
  reaches the record's own sensitive-path floor and is judged by the record before it.

On `workflow_run`, a push-triggered run on the default branch of any workflow but Merge watch
that concludes `failure`, `cancelled`, `timed_out` or `startup_failure` records an escape,
`red-default-branch`, naming the merged PR of the run's commit, unless such a record is
already open. Manual cancellation or a `cancel-in-progress` group on the default branch
may open a false record; that cost is accepted because a false record beats a lost one.

A format it can't read, or a GitHub read that fails, counts that review or fact as absent, so
it yields a false miss record, never a blocked merge. A record whose title and `Observed:`
line an open record already has isn't opened again, so a rerun adds nothing. Two runs at once
can each read no open record, so two workflows failing together may open two
`red-default-branch` records: a concurrency group would cancel a pending run and lose its
record instead.

The `Risk:` and `Reverts:` lines and the record are read with the gate script's parser,
imported from beside this file. Python 3's standard library at the 3.9 level, plus `gh`.
"""

import argparse
import json
import os
import re
import subprocess
import sys

sys.dont_write_bytecode = True

import gate  # noqa: E402

LABEL = "miss"
FOUND_BY = "Merge watch"
WORKFLOW = ".github/workflows/merge-watch.yml"
RECORD = ".github/governance/record.yml"

REVIEWER_CONTEXT = "Reviewer"

# The Merge summary's fixed first two lines (docs/agents/review.md, Merge summary, On the PR).
SUMMARY_TITLE = re.compile(r"## Merge summary: (low|medium|high) at ([0-9a-f]{7})")
SUMMARY_REVIEWS = "Required reviews: "
KINDS = ("self-verification", "bot-1", "bot-2", "reviewer", "security")
BOT_SLOTS = ("bot-1", "bot-2")
MERGE_SUMMARY = "merge-summary"
REQUIRED = {
    "low": ("self-verification",),
    "medium": ("self-verification", "bot-1", "reviewer"),
    "high": ("self-verification", "bot-1", "bot-2", "reviewer"),
}
# A bot slot's state names its provider; `none` only when no enabled provider is left.
SLOT_STATES = {"clear": "provider", "fallback": "provider", "unavailable": "provider",
               "waived": "provider or none", "no-provider": "none"}
OTHER_STATES = ("clear", "waived")
_ITEM = re.compile(r"([a-z0-9-]+)=([a-z-]+)(?:\(([a-z]+)\))?")
NO_PROVIDER = "none"

# habit's waiver: the first line of a PR comment by the repository owner. The item is a
# review kind, or a row of the repository's verification table, which Merge watch doesn't judge.
WAIVER = re.compile("Waiver: (%s|verification \"[^\"\n]+\") at ([0-9a-f]{40}) \u2014 (\\S.*)" % "|".join(KINDS))

# The record at the merge's base names the enabled review bots, from version 3.
REVIEW_BOTS_VERSION = 3


class ReadError(Exception):
    """GitHub couldn't give a fact Merge watch reads."""


class NotFound(ReadError):
    """GitHub answered that the file isn't there: HTTP 404 with the message `Not Found`."""


def _same_login(a, b):
    return bool(a) and bool(b) and a.lower() == b.lower()


def _read(read, path, default):
    try:
        return read(path)
    except ReadError:
        return default


def record(merged_pr, kind, category, observed):
    """One miss record: its title, its six field lines and the `miss` label."""
    title = "Miss: %s, %s" % (kind, category)
    if merged_pr is not None:
        title += " in #%d" % merged_pr
    lines = (
        "Merged PR: %s" % ("#%d" % merged_pr if merged_pr is not None else "none"),
        "Kind: %s" % kind,
        "Category: %s" % category,
        "Observed: %s" % observed,
        "Found by: %s" % FOUND_BY,
        "Bug issue: none",
    )
    return {"title": title, "body": "\n".join(lines) + "\n", "labels": [LABEL]}


def _field(body, name):
    for line in (body or "").replace("\r\n", "\n").split("\n"):
        if line.startswith(name + ": "):
            return line[len(name) + 2:]
    return None


def _open_records(read, repository):
    issues = _read(read, "repos/%s/issues?labels=%s&state=open" % (repository, LABEL), [])
    return [issue for issue in issues if "pull_request" not in issue]


def _merged_pr(read, repository, default_branch, sha):
    """(the PR merged as sha, or None; whether sha is in another merged PR's history). ReadError when unread."""
    merged = [
        pull for pull in read("repos/%s/commits/%s/pulls" % (repository, sha))
        if pull.get("merged_at") and (pull.get("base") or {}).get("ref") == default_branch
    ]
    for pull in merged:
        if pull.get("merge_commit_sha") == sha:
            return pull, False
    return None, bool(merged)


class Pull(object):
    """One merged PR's facts on its head, each read from GitHub once, when first needed."""

    def __init__(self, read, repository, number, head):
        self.read, self.repository, self.number, self.head = read, repository, number, head
        self._cache = {}

    def _get(self, path):
        if path not in self._cache:
            self._cache[path] = _read(self.read, path, [])
        return self._cache[path]

    def comments(self):
        return self._get("repos/%s/issues/%d/comments" % (self.repository, self.number))

    def reviews(self):
        return self._get("repos/%s/pulls/%d/reviews" % (self.repository, self.number))

    def check_runs(self, name):
        return self._get("repos/%s/commits/%s/check-runs?check_name=%s&filter=all" % (self.repository, self.head, name))

    def statuses(self):
        return self._get("repos/%s/commits/%s/statuses" % (self.repository, self.head))


# One reader per review bot: whether its review completed on the head, findings or not.
# Everything specific to a provider lives here (docs/agents/review.md, Review bots).

CODEX_LOGIN = "chatgpt-codex-connector[bot]"
CODEX_MARKER = re.compile(r"<!-- codex-review-state:v1 (\{.*?\}) -->", re.S)
COPILOT_LOGIN = "copilot-pull-request-reviewer[bot]"
COPILOT_CHECK = "copilot-pull-request-reviewer"


def _codex(pull):
    """A `codex-review-state:v1` marker in the Codex review bot's comment, for the head, completed."""
    for comment in pull.comments():
        if (comment.get("user") or {}).get("login") != CODEX_LOGIN:
            continue
        for match in CODEX_MARKER.finditer(comment.get("body") or ""):
            try:
                review = json.loads(match.group(1)).get("code_review")
            except (ValueError, AttributeError):
                continue
            if isinstance(review, dict) and review.get("commit_sha") == pull.head and review.get("status") == "completed":
                return True
    return False


def _copilot(pull):
    """A Copilot code review object on the head, corroborated by its check run completed there.

    Copilot leaves a review by its bot login with `is_copilot_code_review` true and `commit_id`
    the head, and a `copilot-pull-request-reviewer` check run on the head. A comment by its
    login without a review object, or a review for an older head, is no review of this head.
    Only `success` was observed on a finished run, so only it counts.
    """
    reviewed = any(
        (review.get("user") or {}).get("login") == COPILOT_LOGIN
        and review.get("is_copilot_code_review") is True
        and review.get("commit_id") == pull.head
        and review.get("state") != "PENDING"
        for review in pull.reviews()
    )
    return reviewed and any(
        run.get("name") == COPILOT_CHECK and run.get("status") == "completed" and run.get("conclusion") == "success"
        for run in pull.check_runs(COPILOT_CHECK)
    )


PROVIDERS = {"codex": _codex, "copilot": _copilot}


def _reviewer(pull, agent_account):
    """Whether the agent account's newest `Reviewer` status on the head is success; GitHub lists the newest first."""
    for status in pull.statuses():
        if status.get("context") == REVIEWER_CONTEXT and _same_login((status.get("creator") or {}).get("login"), agent_account):
            return status.get("state") == "success"
    return False


def parse_reviews(line, tier):
    """The `Required reviews:` line as {kind: (state, provider or None)}, or None when it doesn't read.

    It reads when every item is `<kind>=<state>`, a bot slot's state with its provider in
    parentheses, the kinds in their order and none twice, and it lists every kind the tier
    requires. A provider is one `PROVIDERS` holds, or `none` where the state allows it, and
    `fallback` stands only in `bot-1` at medium.
    """
    if not line.startswith(SUMMARY_REVIEWS):
        return None
    states, order = {}, []
    for item in line[len(SUMMARY_REVIEWS):].rstrip(" \t").split(", "):
        match = _ITEM.fullmatch(item)
        if not match or match.group(1) not in KINDS or match.group(1) in states:
            return None
        kind, state, provider = match.groups()
        if kind in BOT_SLOTS:
            allowed = SLOT_STATES.get(state)
            if allowed is None or provider is None:
                return None
            if provider == NO_PROVIDER and NO_PROVIDER not in allowed:
                return None
            if provider != NO_PROVIDER and (provider not in PROVIDERS or "provider" not in allowed):
                return None
            # Only medium falls back: at high both bots are asked at once (review.md, Review bots).
            if state == "fallback" and (tier, kind) != ("medium", "bot-1"):
                return None
        elif state not in OTHER_STATES or provider is not None:
            return None
        states[kind] = (state, provider)
        order.append(KINDS.index(kind))
    if order != sorted(order) or any(kind not in states for kind in REQUIRED[tier]):
        return None
    return states


def _summary(pull, agent_account, tier):
    """The newest Merge summary for the tier and head, parsed; None when absent or its line doesn't read."""
    for comment in reversed(pull.comments()):
        if not _same_login((comment.get("user") or {}).get("login"), agent_account):
            continue
        lines = (comment.get("body") or "").replace("\r\n", "\n").split("\n")
        title = SUMMARY_TITLE.fullmatch(lines[0].rstrip(" \t"))
        if title and title.group(1) == tier and title.group(2) == pull.head[:7]:
            return parse_reviews(lines[1], tier) if len(lines) > 1 else None
    return None


def waived(pull, owner):
    """The review kinds the repository owner waived for this head, each by its own comment."""
    kinds = set()
    for comment in pull.comments():
        if not _same_login((comment.get("user") or {}).get("login"), owner):
            continue
        first = (comment.get("body") or "").replace("\r\n", "\n").split("\n")[0].rstrip(" \t")
        match = WAIVER.fullmatch(first)
        if match and match.group(2) == pull.head and match.group(1) in KINDS:
            kinds.add(match.group(1))
    return kinds


def earlier_version_missing(pull, agent_account, tier):
    """What every version requires of a merge onto a base below version 3: the Reviewer's
    status from medium, and the agent account's Merge summary titled for the tier and head with
    a `Required reviews:` line, whatever kinds that version's line names."""
    missing = []
    if tier != "low" and not _reviewer(pull, agent_account):
        missing.append("reviewer")
    for comment in reversed(pull.comments()):
        if not _same_login((comment.get("user") or {}).get("login"), agent_account):
            continue
        lines = (comment.get("body") or "").replace("\r\n", "\n").split("\n")
        title = SUMMARY_TITLE.fullmatch(lines[0].rstrip(" \t"))
        if title and title.group(1) == tier and title.group(2) == pull.head[:7]:
            if len(lines) > 1 and lines[1].startswith(SUMMARY_REVIEWS):
                return missing
            break
    return missing + [MERGE_SUMMARY]


def enabled_bots(read, repository, ref):
    """(the record's version at ref, its enabled review bots); (None, []) when it can't be read.

    NotFound when GitHub answers that ref holds no record."""
    try:
        text = read("repos/%s/contents/%s?ref=%s" % (repository, RECORD, ref))
        parsed = gate.parse_record(text.encode("utf-8"))
    except NotFound:
        raise
    except (ReadError, gate.RecordError, AttributeError):
        return None, []
    return parsed["version"], [bot for bot in parsed["confirmed"].get("review_bots", []) if bot in PROVIDERS]


def missing_reviews(pull, agent_account, owner, tier, bots):
    """Each review missing from the head at the tier: Merge summary kinds in their order, then `merge-summary`."""
    summary = _summary(pull, agent_account, tier)
    waivers = waived(pull, owner)
    missing = set()
    slots = [kind for kind in REQUIRED[tier] if kind in BOT_SLOTS and kind not in waivers]
    completed = {}

    def done(provider):
        if provider not in completed:
            completed[provider] = provider in bots and PROVIDERS[provider](pull)
        return completed[provider]

    if summary is not None:
        used = set()
        for slot in slots:
            state, provider = summary[slot]
            if state in ("clear", "fallback") and provider not in used and done(provider):
                used.add(provider)
            else:
                missing.add(slot)
    elif slots:
        filled = []
        for bot in bots:
            if len(filled) == len(slots):
                break
            if done(bot):
                filled.append(bot)
        missing.update(slots[len(filled):])
    if "reviewer" in REQUIRED[tier] and "reviewer" not in waivers and not _reviewer(pull, agent_account):
        missing.add("reviewer")
    for kind in ("self-verification", "security"):
        if summary is not None and kind in summary and summary[kind][0] == "waived" and kind not in waivers:
            missing.add(kind)
    ordered = [kind for kind in KINDS if kind in missing]
    if summary is None:
        ordered.append(MERGE_SUMMARY)
    return ordered


def _judge_pull(read, repository, agent_account, pull, squash, base, notes):
    records = []
    number, head = pull["number"], pull["head"]["sha"]
    body = gate.parse_body(pull.get("body") or "")
    reverts = body["reverts"]
    if isinstance(reverts, dict):
        try:
            reverted, _ = _merged_pr(read, repository, pull["base"]["ref"], reverts["sha"])
        except ReadError:
            reverted = None
        records.append(record(
            reverted["number"] if reverted else None, "escape", "revert",
            "#%d, merged as %s, reverted %s, and its body had a `Reverts:` line." % (number, squash, reverts["sha"]),
        ))
    elif reverts is not None:
        records.append(record(
            None, "escape", "revert",
            "#%d, merged as %s, has a `Reverts:` line that doesn't read (%s), so the reverted PR is unknown."
            % (number, squash, reverts),
        ))
    risk = body["risk"]
    if isinstance(risk, dict):
        tier, declared = risk["tier"], "declared %s" % risk["tier"]
    else:
        tier, declared = "high", "declared no readable tier (its `Risk:` line is %s), judged at high" % risk
    try:
        version, bots = enabled_bots(read, repository, base)
    except NotFound:
        notes.append("#%d merged onto a base with no governance record, so the record it adds names the enabled "
                     "review bots." % number)
        try:
            version, bots = enabled_bots(read, repository, squash)
        except NotFound:
            version, bots = None, []
    facts = Pull(read, repository, number, head)
    if version is not None and version < REVIEW_BOTS_VERSION:
        notes.append("#%d merged onto a base whose record is at version %d; its review bots follow that version's "
                     "rules, which this script doesn't judge." % (number, version))
        missing = earlier_version_missing(facts, agent_account, tier)
    else:
        missing = missing_reviews(facts, agent_account, repository.split("/")[0], tier, bots)
    if missing:
        records.append(record(
            number, "process miss", "missing-review",
            "Merged head %s, %s, lacks: %s." % (head, declared, ", ".join(missing)),
        ))
    return records


def _on_push(event, read, repository, default_branch, agent_account, notes):
    records = []
    # Each commit's parent: the one before it in the push, or the push's `before` for the first.
    base = event.get("before")
    for commit in event.get("commits") or []:
        sha = commit["id"]
        parent, base = base, sha
        try:
            pull, in_history = _merged_pr(read, repository, default_branch, sha)
        except ReadError:
            pull, in_history = None, False
        if pull is not None:
            records.extend(_judge_pull(read, repository, agent_account, pull, sha, parent, notes))
        elif not in_history:
            records.append(record(
                None, "process miss", "push-without-pr",
                "Commit %s was pushed to %s with no merged PR." % (sha, default_branch),
            ))
    return records


def _on_workflow_run(event, read, repository, default_branch, open_records):
    run = event["workflow_run"]
    if (
        run.get("event") != "push"
        or run.get("conclusion") not in ("failure", "cancelled", "timed_out", "startup_failure")
        or run.get("head_branch") != default_branch
        or (run.get("path") or "").split("@")[0] == WORKFLOW
    ):
        return []
    if any(_field(issue.get("body"), "Category") == "red-default-branch" for issue in open_records):
        return []
    sha = run["head_sha"]
    try:
        pull, _ = _merged_pr(read, repository, default_branch, sha)
    except ReadError:
        pull = None
    return [record(
        pull["number"] if pull else None, "escape", "red-default-branch",
        "Workflow %s concluded %s on its push-triggered run %s at commit %s."
        % (run.get("name"), run.get("conclusion"), run.get("html_url"), sha),
    )]


def decide(event_name, event, agent_account, read, notes=None):
    """The miss records to open for one event.

    `read(path)` returns the JSON list GitHub gives for a REST path, every page joined (a
    check-runs answer's `check_runs`), a file's text for a `contents` path, or raises
    ReadError. `agent_account` is the record's, or None when the record doesn't parse. Each
    record is {"title", "body", "labels"}. A fact worth saying that records nothing is
    appended to `notes`, when given.
    """
    notes = [] if notes is None else notes
    repository = event["repository"]["full_name"]
    default_branch = event["repository"]["default_branch"]
    if event_name == "push" and event.get("ref") == "refs/heads/" + default_branch:
        open_records = _open_records(read, repository)
        records = _on_push(event, read, repository, default_branch, agent_account, notes)
    elif event_name == "workflow_run":
        open_records = _open_records(read, repository)
        records = _on_workflow_run(event, read, repository, default_branch, open_records)
    else:
        return []
    seen = set((issue.get("title"), _field(issue.get("body"), "Observed")) for issue in open_records)
    return [rec for rec in records if (rec["title"], _field(rec["body"], "Observed")) not in seen]


# The entry the workflow runs.

PER_PAGE = 100


class GitHub(object):
    """`read` through `gh api`, every page of a list; each path that couldn't be read is kept in `unreadable`."""

    def __init__(self):
        self.unreadable = []

    def __call__(self, path):
        if "/contents/" in path:
            return self._file(path)
        items, page = [], 1
        while True:
            paged = "%s%sper_page=%d&page=%d" % (path, "&" if "?" in path else "?", PER_PAGE, page)
            result = subprocess.run(["gh", "api", paged], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            try:
                if result.returncode != 0:
                    raise ValueError(" ".join(result.stderr.decode("utf-8", "replace").split()) or "gh failed")
                data = json.loads(result.stdout.decode("utf-8"))
                if isinstance(data, dict) and isinstance(data.get("check_runs"), list):
                    data = data["check_runs"]
                if not isinstance(data, list):
                    raise ValueError("the answer isn't a list")
            except ValueError as error:
                self.unreadable.append("%s: %s" % (paged, error))
                raise ReadError(path)
            items.extend(data)
            if len(data) < PER_PAGE:
                return items
            page += 1


    def _file(self, path):
        """A file's text at a ref, from the contents API's raw form; NotFound on GitHub's own answer that it isn't there."""
        result = subprocess.run(["gh", "api", "-H", "Accept: application/vnd.github.raw", path],
                                stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if result.returncode != 0 and _not_found(result.stdout):
            raise NotFound(path)
        try:
            if result.returncode != 0:
                raise ValueError(" ".join(result.stderr.decode("utf-8", "replace").split()) or "gh failed")
            return result.stdout.decode("utf-8")
        except ValueError as error:
            self.unreadable.append("%s: %s" % (path, error))
            raise ReadError(path)


def _not_found(stdout):
    """Whether gh printed GitHub's error body for a missing file: status 404, message `Not Found`."""
    try:
        data = json.loads(stdout.decode("utf-8"))
    except ValueError:
        return False
    return isinstance(data, dict) and data.get("status") == "404" and data.get("message") == "Not Found"


def _post(repository, rec):
    """Open the record as an issue; True when GitHub took it."""
    posted = subprocess.run(
        ["gh", "api", "--method", "POST", "repos/%s/issues" % repository, "--input", "-"],
        input=json.dumps(rec, sort_keys=True).encode("utf-8"),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    return posted.returncode == 0


def main(argv=None):
    parser = argparse.ArgumentParser(description="Merge watch's miss records for the event in GITHUB_EVENT_PATH.")
    parser.add_argument("--post", action="store_true", help="open each record as a `miss` issue")
    args = parser.parse_args(argv)
    with open(os.environ["GITHUB_EVENT_PATH"], encoding="utf-8") as handle:
        event = json.load(handle)
    event_name = os.environ["GITHUB_EVENT_NAME"]
    try:
        with open(os.path.join(os.getcwd(), *RECORD.split("/")), "rb") as handle:
            agent_account = gate.parse_record(handle.read())["agent_account"]
    except (OSError, gate.RecordError) as error:
        agent_account = None
        print("UNREADABLE %s: %s; no comment or status counts as the agent account's" % (RECORD, error))
    github = GitHub()
    notes = []
    records = decide(event_name, event, agent_account, github, notes)
    failed = agent_account is None or bool(github.unreadable)
    for line in github.unreadable:
        print("UNREADABLE " + line)
    for line in notes:
        print("NOTE " + line)
    for rec in records:
        print("MISS %s. %s" % (rec["title"], _field(rec["body"], "Observed")))
        if args.post and not _post(event["repository"]["full_name"], rec):
            print("FAIL opening the record %s" % rec["title"])
            failed = True
    if not records:
        print("No miss in this %s event." % event_name)
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
